/**
 * The GoWay logo, as geometry.
 *
 * This file is the MASTER. `goway.source.svg` beside it is the unmodified
 * artwork as it was delivered — 118 kB, twelve `<path>` elements buried under
 * 69 `<g>` and five nested `clipPath`s, with a `viewBox` 42% taller and 23%
 * wider than the ink it contains. It is kept for provenance and is imported by
 * nothing; every GoWay logo anywhere is drawn from the data below.
 *
 * ## What was done to it, and how that was proved
 *
 * The export tool's structure carried no information. Every transform in it was
 * a pure translation, so each was folded into its path's coordinates; the clip
 * paths turned out to clip nothing, so they went; the `viewBox` was cropped to
 * the measured ink box (x 210.51, y 256.45, w 1404.59, h 887.91), which is what
 * removes the phantom padding an `<img>` used to inherit; and coordinates were
 * re-encoded relative to a QUANTISED current point at two decimal places, so
 * the rounding error stays bounded at 0.005 units instead of accumulating along
 * a contour. 118,067 bytes became 53,496 — 55% smaller.
 *
 * That is a lot of surgery on artwork, so it was measured rather than asserted.
 * Original and rewrite were rendered by the same headless Chromium at
 * 1405x888 (one unit per pixel) and compared pixel by pixel:
 *
 *   flattened, NO rounding at all   0.598% of pixels differ, max delta 70/255
 *   this file (relative, 2 dp)      0.630% of pixels differ, max delta 70/255
 *   the same data at 0 dp           44.6% differ, max delta 255  — destroyed
 *
 * The 0.598% is the floor, not the error: it is what removing the nested
 * `<g clip-path>` layers costs on its own, because Chromium composites each one
 * through an offscreen buffer and antialiases the seam between the outline and
 * the fill differently when it does. Rounding to two decimal places adds 0.03
 * percentage points on top of that, every differing pixel is an antialiased
 * edge blend, and the average difference on those pixels is 3 levels out of
 * 255. At the size the badge actually draws (90 px wide) the two renders differ
 * on 165 of 5,130 pixels by an average of 4 levels — which is to say, they do
 * not differ. **0 dp is recorded because it is a trap**: integer coordinates
 * collapse short segments, the non-zero fill rule flips, and the wordmark comes
 * apart. Do not "simplify" the precision further.
 *
 * ## Why geometry and not a file
 *
 * Because a logo that arrives over the network is a logo that can fail to
 * arrive. `MapBrand` renders these paths through `react-native-svg`, which
 * makes the brand part of the bundle on web and native alike: no second
 * request, no 404 after a bad deploy, nothing an embedder's page can interfere
 * with, and one implementation rather than a web fork and a native fork that
 * drift. `scripts/build-brand.ts` writes `public/brand/*.svg` back out FROM
 * this file for the cases that genuinely need a URL (the favicon, an `<img>` in
 * somebody's README), and `brand:check` fails if those files drift.
 *
 * ## Draw order is load-bearing
 *
 * The outlines are drawn first and the fills over them, and "G" and "O"
 * overlap horizontally (x 869.8–952.0), so O's outline sits UNDER G's fill.
 * Re-sorting this array by ink, or by part, changes the artwork. Filtering it
 * preserves the order and is safe — that is how {@link GOWAY_MARK} is derived.
 */

/**
 * The three colours the artwork is made of, and the only three it may use.
 *
 * These are INK, not theme. Bloom owns `--primary` and `BloomThemeProvider`
 * rewrites it at runtime from the user's chosen Oxy theme; a logo that followed
 * it would be a different logo in every theme, which is the one thing a logo
 * may not be. So GoWay's blue sits BESIDE Bloom's primary rather than
 * overriding it — overriding would also repaint every Bloom control in the app
 * — and `global.css` declares the same two values as `--color-brand-goway` and
 * `--color-brand-goway-tint` for the className side, with
 * `__tests__/artwork.test.ts` failing if the two spellings ever disagree.
 *
 * `way` is a literal white because the "WAY" counters are white in the artwork,
 * not because the surface behind them is light. It stays white on a dark map.
 */
export const GOWAY_INK = {
  /** The heavy outline that carries the mark on any background. */
  outline: '#004aad',
  /** The "GO" bubble fill. */
  go: '#acd0ff',
  /** The "WAY" bubble fill. */
  way: '#ffffff',
} as const;

export type GowayInk = keyof typeof GOWAY_INK;

/** Which letter a path belongs to. `g` alone is {@link GOWAY_MARK}. */
export type GowayPart = 'g' | 'o' | 'w' | 'a' | 'y';

export interface GowayPath {
  /** The letter this contour belongs to. */
  readonly part: GowayPart;
  /** `outline` is drawn first, `fill` over it. */
  readonly layer: 'outline' | 'fill';
  /** Which of {@link GOWAY_INK} paints it. */
  readonly ink: GowayInk;
  /** SVG path data, in the wordmark's coordinate space. */
  readonly d: string;
}

