/**
 * The full lockup: "GO" stacked over "WAY", cropped to its ink.
 *
 * 1.582:1. Everything in {@link GOWAY_PATHS}, in order.
 */
export const GOWAY_WORDMARK = {
  viewBox: '0 0 1404.59 887.9',
  paths: GOWAY_PATHS,
} as const;

/**
 * The compact mark: the "G" bubble alone, a 0.98:1 near-square.
 *
 * Not a second drawing — the same two contours as the wordmark, seen through a
 * `viewBox` that crops to them. That is why it can never drift from the logo.
 *
 * **Its honest limit is 16 px.** Rendered at 16, 32 and 64 CSS px and looked
 * at: at 32 and above it is unmistakably a bubble G, spur and all. At 16 the
 * heavy outline closes the counter and it reads as a round blue letter-shape
 * rather than as a G. That is acceptable here only because it is shipped as
 * SVG — a 16 px tab slot on a 2x display rasterises it at 32 device pixels,
 * where it reads. Do NOT bake a 16x16 PNG from this and call it a favicon.
 * The wordmark is worse: it is unreadable below about 48 px, which is why it
 * is never the icon.
 */
export const GOWAY_MARK = {
  viewBox: '288.87 0 452.59 461.62',
  paths: GOWAY_PATHS.filter((path) => path.part === 'g'),
} as const;

/** What {@link GOWAY_WORDMARK} and {@link GOWAY_MARK} both are. */
export interface GowayArtwork {
  readonly viewBox: string;
  readonly paths: readonly GowayPath[];
}

/** Width ÷ height, from the `viewBox`, for laying a logo out without magic numbers. */
export function aspectRatio(artwork: GowayArtwork): number {
  const [, , width, height] = artwork.viewBox.split(' ').map(Number);
  return width / height;
}
